\text{dot((-3,1),linewidth(6pt) + dotstyle);}
\text{dot((-3,0),linewidth(6pt) + dotstyle);}
\text{dot((-2,0),linewidth(6pt) + dotstyle);}
\text{dot((-2,1),linewidth(6pt) + dotstyle);}
\text{dot((-2,2),linewidth(6pt) + dotstyle);}
\text{dot((-2,3),linewidth(6pt) + dotstyle);}
\text{dot((-2,4),linewidth(6pt) + dotstyle);}
\text{dot((-1,4),linewidth(6pt) + dotstyle);}
\text{dot((0,4),linewidth(6pt) + dotstyle);}
\text{dot((1,4),linewidth(6pt) + dotstyle);}
\text{dot((1,3),linewidth(6pt) + dotstyle);}
